import React, { useState, useEffect } from 'react';
import { PickList } from 'primereact/picklist';
import { ProductService } from './Service/ProductService';

export default function Filter() {
    const [source, setSource] = useState([]);
    const [target, setTarget] = useState([]);

    useEffect(() => {
        ProductService.getProductsSmall().then((data) => setSource(data));
    }, []);

    const onChange = (event) => {
        setSource(event.source);
        setTarget(event.target);
    };

    const itemTemplate = (item) => {
        return (
            <div className="fxb wrap pd5 fvc gp4">
                <img className="w60 h50 shadow-md rds2" src={`https://primefaces.org/cdn/primereact/images/product/${item.image}`} alt={item.name} />
                <div className="fvc gp3 column">
                    <span className="font-bold">{item.name}</span>
                    <div className="fxb fvc gp3">
                        <i className="pi pi-tag text-sm"></i>
                        <span>{item.category}</span>
                    </div>
                </div>
                <span className="font-bold font-size20 mgl-auto">${item.price}</span>
            </div>
        );
    };

    return (
        <PickList dataKey="id" source={source} target={target} onChange={onChange} itemTemplate={itemTemplate} filter filterBy="name" breakpoint="1280px"
            sourceHeader="Available" targetHeader="Selected" sourceStyle={{ height: '24rem' }} targetStyle={{ height: '24rem' }}
            sourceFilterPlaceholder="Search by name" targetFilterPlaceholder="Search by name" />
    );

}